// ─── BRA SIZE CONVERSION TABLES ──────────────────────────────────────────────
// UK band → EU band (UK + 32 = EU, e.g. UK 32 = EU 64… but in practice EU uses +28 for some brands)
// Convention used here: EU = UK + 32 (most common internationally)
const UK_TO_EU_BAND = { 28:60, 30:65, 32:70, 34:75, 36:80, 38:85, 40:90, 42:95, 44:100, 46:105 };
// US bands are the same numbers as UK
// Cup conversions: UK/US cups vs EU cups (EU skips DD, calls it E, etc.)
const UK_CUP_TO_EU = { A:"A", B:"B", C:"C", D:"D", DD:"E", E:"F", F:"G", FF:"H", G:"I", GG:"J", H:"K" };
const UK_CUP_TO_US = { A:"A", B:"B", C:"C", D:"D", DD:"DD", E:"DDD", F:"F", FF:"G", G:"G", GG:"H", H:"H" };
// All valid UK cup sizes in order
const UK_CUPS = ["AA","A","B","C","D","DD","E","F","FF","G","GG","H","HH","J","JJ","K"];
// All valid UK bands
const UK_BANDS = [28,30,32,34,36,38,40,42,44,46];

// Parse a bra size string like "34B" or "34DD" → { band: 34, cup: "B" }
function parseBraSize(s) {
  if (!s) return null;
  const m = s.trim().toUpperCase().match(/^(\d+)(AA|DD|FF|GG|HH|JJ|A|B|C|D|E|F|G|H|J|K)$/);
  if (!m) return null;
  return { band: parseInt(m[1]), cup: m[2] };
}

