// ─── CONFIDENCE HELPERS ──────────────────────────────────────────────────────
const confColor = (v) => v >= 85 ? "#1e6e40" : v >= 70 ? "#7a6020" : "#9e3520";
const confBg    = (v) => v >= 85 ? "#e6f4eb" : v >= 70 ? "#fdf6e3" : "#fde8e4";
const confLabel = (v) => v >= 85 ? "High confidence" : v >= 70 ? "Moderate — verify" : "Low — always check";
const monthsOld = (dateStr) => {
  const [yr, mo] = dateStr.split("-").map(Number);
  const d = new Date(); return (d.getFullYear()-yr)*12 + d.getMonth()+1-mo;
};

// ─── AIRTABLE SUBMIT ─────────────────────────────────────────────────────────
async function submitToAirtable(data) {
  if (CONFIG.DEMO_MODE) {
    await new Promise(r => setTimeout(r, 1200));
    return { success: true, demo: true };
  }
  const res = await fetch("/.netlify/functions/submit", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data),
  });
  if (!res.ok) throw new Error(`Submit error: ${res.status}`);
  return { success: true };
}

// Distance from a body measurement to a size row. If the brand publishes a range
// (row.rng[key] = [min,max]) any value inside it scores 0; otherwise distance to the single value.
function dimDist(v, s, key) {
  if (!v) return 0;
  const r = key==="bust" ? (s.rng?.bust || s.rng?.chest) : s.rng?.[key];
  if (Array.isArray(r)) return v < r[0] ? r[0]-v : v > r[1] ? v-r[1] : 0;
  const x = key==="bust" ? (s.bust || s.chest) : s[key];
  return x ? Math.abs(v - x) : 0;
}

// ─── GOOGLE OAUTH ────────────────────────────────────────────────────────────
function useGoogleAuth(onSuccess) {
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (CONFIG.DEMO_MODE) { setLoaded(true); return; }
    if (!GOOGLE_READY) return;
    const s = document.createElement("script");
    s.src = "https://accounts.google.com/gsi/client";
    s.async = true;
    s.defer = true;
    s.onload = () => {
      window.google.accounts.id.initialize({
        client_id: CONFIG.GOOGLE_CLIENT_ID,
        callback: (res) => {
          const b64 = res.credential.split(".")[1].replace(/-/g,"+").replace(/_/g,"/");
          const payload = JSON.parse(decodeURIComponent(atob(b64).split("").map(c=>"%"+("00"+c.charCodeAt(0).toString(16)).slice(-2)).join("")));
          onSuccess({ name: payload.name, email: payload.email, picture: payload.picture, provider: "google" });
        },
      });
      setLoaded(true);
    };
    document.head.appendChild(s);
    return () => { try { document.head.removeChild(s); } catch {} };
  }, []);
  return loaded;
}

